import{_ as l,o as a,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2021-03-11","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-03-11","date":"2021-03-11T00:00:00.000Z","updated":"2021-03-18T00:00:00.000Z","tags":["Ceph","Performance","BlueStore","RocksDB","Benchmarking"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-03-11.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-03-11.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Performance_Meeting_2021-03-11.md"};function o(n,e,s,h,u,c){return a(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>OMAP性能基准测试</strong></p><ul><li>会议讨论了两个新的Pull Request (PR)，一个由会议主持人提出，旨在为对象存储测试套件实现一个快速且简单的OMAP基准测试，另一个由Gabby提出，目的是从RocksDB中移除分配。</li><li>会议主持人提出了增加写入多个对象和大量键的能力，并进行时间测试的改进建议。</li></ul></li><li><p><strong>其他PR更新</strong></p><ul><li>讨论了Shuhan提交的PR，该PR涉及将Alien存储线程分散到不同的CPU核心，以及Adam的PR，用于区分BlueFS中的Buffered和Direct IO。</li><li>还讨论了Seth的PR，该PR涉及并发检索设备数据，目前仍在讨论和改进中。</li></ul></li><li><p><strong>BlueStore性能问题</strong></p><ul><li>会议重点讨论了BlueStore的性能问题，特别是在OMAP迭代和RocksDB代码路径方面。</li><li>讨论了可能的性能瓶颈，如块缓存争用和RocksDB的迭代性能。</li><li>提出了一些理论，如内存使用情况可能影响性能，特别是BlueStore和FileStore之间的差异。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>会议主持人计划继续深入研究BlueStore的性能问题，特别是理解RocksDB代码和块缓存的使用情况。</li><li>鼓励团队成员查看基准测试代码，并提供反馈和改进建议。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了继续深入研究BlueStore性能问题的必要性，特别是OMAP性能和RocksDB的使用。</li><li>确定了需要进一步讨论和改进的PR，包括Gabby和Shuhan的PR。</li></ul><h4 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h4><ul><li>会议主持人将继续工作于OMAP性能基准测试，并分享进展。</li><li>团队成员被鼓励查看和评论相关的PR，以帮助改进和优化。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了FileStore和BlueStore在内存使用和性能方面的差异，以及可能的解释和解决方案。</li><li>提到了RocksDB的块缓存和迭代性能，以及可能的改进方向。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议结束时，主持人感谢大家的参与，并提醒大家下周再见。会议强调了持续关注和改进Ceph存储系统的性能问题的重要性。</p>',11)])])}const P=l(r,[["render",o]]);export{p as __pageData,P as default};
